import React, { useState } from "react";

export default function BfProjectBirthday() {
    const [opened, setOpened] = useState(false);
    const [letterOpen, setLetterOpen] = useState(false);
    const [candlesOff, setCandlesOff] = useState(false);
    const [pin, setPin] = useState("");
    const [pinError, setPinError] = useState(false);
    const [hasAccess, setHasAccess] = useState(false);

  const memories = [
    { image: "image1.jpeg", alt: "Kenangan foto bersama", caption: "My favorite person ♡" },
    { image: "image2.jpeg", alt: "Momen manis bersama", caption: "Little happy moments ♡" },
    { image: "image3.jpeg", alt: "Kolase foto photobooth berdua", caption: "Always you, always us ♡", centered: true },
    { image: "image4.jpeg", alt: "Bermain gokart bersama", caption: "Adventures with you ♡" },
    { image: "image5.jpeg", alt: "Foto berdua di depan cermin", caption: "My favorite view ♡" },
    { image: "image6.jpeg", alt: "Kenangan bersama di arena permainan", caption: "Making memories ♡" },
    { image: "image7.jpeg", alt: "Foto berdua di cermin", caption: "Just the two of us ♡" },
    { image: "image8.jpeg", alt: "Foto-foto kenangan masa kecil", caption: "A story that started early ♡", centered: true },
  ];

  const hearts = Array.from({ length: 18 }, (_, i) => i);

  if (!hasAccess) {
    return (
      <main className="pin-gate">
        <section className="pin-gate__content" aria-labelledby="pin-title">
          <span className="pin-gate__mark" aria-hidden="true">♡</span>
          <p className="eyebrow">A LITTLE SURPRISE FOR YOU</p>
          <h1 id="pin-title">Ada kejutan untukmu</h1>
          <p className="pin-gate__description">
            Enter the Date we started dating as the login PIN.
          </p>

          <form
            className="pin-gate__form"
            onSubmit={(event) => {
              event.preventDefault();
              if (pin === "210126") {
                setHasAccess(true);
              } else {
                setPinError(true);
              }
            }}
          >
            <label htmlFor="birthday-pin">PIN kejutan</label>
            <input
              id="birthday-pin"
              type="text"
              inputMode="numeric"
              autoComplete="one-time-code"
              placeholder="21 01 26"
              value={pin.replace(/(\d{2})(?=\d)/g, "$1 ")}
              aria-invalid={pinError}
              aria-describedby={pinError ? "pin-error" : undefined}
              onChange={(event) => {
                setPin(event.target.value.replace(/\D/g, "").slice(0, 6));
                setPinError(false);
              }}
            />
            {pinError && (
              <p className="pin-gate__error" id="pin-error" role="alert">
                PIN belum tepat. Coba lagi, ya.
              </p>
            )}
            <button className="main-button" type="submit">
              Buka website ♡
            </button>
          </form>
        </section>
      </main>
    );
  }

  return (
    <main className="birthday">
      <div className="floating-hearts">
        {hearts.map((heart) => (
          <span
            key={heart}
            style={{
              left: `${(heart * 37) % 100}%`,
              animationDelay: `${(heart % 8) * 0.8}s`,
              fontSize: `${14 + (heart % 4) * 5}px`,
            }}
          >
            {heart % 2 === 0 ? "♡" : "♥"}
          </span>
        ))}
      </div>

      <nav className="navbar">
        <a href="#home" className="brand">
          ♡ OUR LITTLE WORLD
        </a>
        <div>
          <a href="#home">Home</a>
          <a href="#memories">Memories</a>
          <a href="#letter">For You</a>
        </div>
      </nav>

      <section className="hero" id="home">
        <div className="hero-text">
          <p className="eyebrow">A SPECIAL DAY FOR SOMEONE SPECIAL</p>
          <h1>
            Hey, Birthday
            <br />
            <span>Boy! ♡</span>
          </h1>
          <p className="subtitle">
            Today is all about you, my favorite person.
          </p>

          <button
            className="main-button"
            onClick={() => {
              setOpened(true);
              document
                .getElementById("memories")
                ?.scrollIntoView({ behavior: "smooth" });
            }}
          >
            {opened ? "Your surprise is here ♡" : "Open Your Surprise ♥"}
          </button>
          <p className="tiny-note">made with love, just for you ♡</p>
        </div>

        <div className="cake-area">
          <div className="sparkle sparkle-one">✦</div>
          <div className="sparkle sparkle-two">✧</div>
          <div className="cake">🎂</div>
          <div className="cake-caption">
            {candlesOff
              ? "wish made! ✨"
              : "make a wish, birthday boy ♡"}
          </div>
          <button
            className="wish-button"
            onClick={() => setCandlesOff(!candlesOff)}
          >
            {candlesOff ? "Light the candles 🕯️" : "Blow the candles ✨"}
          </button>
        </div>
      </section>

      {opened && (
        <div className="surprise-message">
          <span>💌</span> Yay! You found your little surprise!
          <span>💗</span>
        </div>
      )}

      <section className="memories section" id="memories">
        <p className="eyebrow">LITTLE THINGS, BIG LOVE</p>
        <h2>Our Little Memories</h2>
        <p className="section-desc">
          Every little moment with you means so much to me.
        </p>

        <div className="memory-grid">
          {memories.map((memory, index) => (
            <article className={`memory-card card-${index + 1}`} key={memory.image}>
              <div className={`memory-image${memory.centered ? " memory-image--centered" : ""}`}>
                <img src={`/image/${memory.image}`} alt={memory.alt} />
              </div>
              <p>{memory.caption}</p>
            </article>
          ))}
        </div>
      </section>

      <section className="letter-section section" id="letter">
        <div className="letter-decoration">💌</div>
        <p className="eyebrow">A LETTER FROM MY HEART</p>
        <h2>To My Birthday Boy</h2>
        <p className="section-desc">
          There is something I want you to know...
        </p>

        <button
          className="main-button"
          onClick={() => setLetterOpen(!letterOpen)}
        >
          {letterOpen ? "Close my letter ♡" : "Read my letter 💌"}
        </button>

        {letterOpen && (
          <article className="love-letter">
            <p>Happy birthday, sayangku! 🎂❤️</p>
            <p>
              Makasih ya udah hadir di hidupku. Aku bersyukur
              bisa kenal kamu dan punya banyak cerita bareng kamu.
            </p>
            <p>
              Di umur yang baru ini, aku harap kamu selalu sehat,
              bahagia, dilancarkan semua urusannya, dan dimudahkan
              dalam mengejar semua impianmu.
            </p>
            <p>
              Jangan terlalu keras sama diri sendiri, ya.
              Aku harap dunia selalu baik sama kamu.
              Semoga aku masih bisa nemenin kamu di banyak
              ulang tahun berikutnya. ♡
            </p>
            <p className="letter-sign">
              With all my love,<br />
              your favorite person ♡
            </p>
          </article>
        )}
      </section>

      <footer>
        <p>Made with ♡ especially for you</p>
        <p className="footer-small">You are loved more than you know.</p>
      </footer>
    </main>
  );
}
